from pathlib import Path
p=Path('index.html')
s=p.read_text()

def one(old,new,label):
    global s
    n=s.count(old)
    if n!=1:
        raise SystemExit(f'guard failed {label}: expected 1, got {n}')
    s=s.replace(old,new)

one("const mins=(a,b)=>Math.max(0,Math.round((new Date(b)-new Date(a))/60000));","const mins=(a,b)=>Math.max(0,Math.ceil((new Date(b)-new Date(a))/60000));",'duration rounding')

one("$('#wdelete')?.addEventListener('click',async()=>{if(confirm('Gewässer wirklich löschen?')){await del('waters',o.id);state.waterProfile=null;$('#modal').close();render()}})","$('#wdelete')?.addEventListener('click',async()=>{let used=d.spots.some(s=>s.waterId===o.id)||d.events.some(e=>e.waterId===o.id)||d.days.some(x=>x.waterId===o.id);if(used){alert('Dieses Gewässer wird bereits von Spots, Ereignissen oder Angeltagen verwendet und kann deshalb nicht gelöscht werden.');return}if(confirm('Gewässer wirklich löschen?')){await del('waters',o.id);state.waterProfile=null;$('#modal').close();render()}})",'water delete guard')

old_spot="$('#sf').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),pp=await imgs(e.target.photos.files),x={...(o||{}),id:o?.id||crypto.randomUUID(),waterId:f.get('waterId'),number:no,label:f.get('label'),lat:+f.get('lat')||'',lon:+f.get('lon')||'',depth:f.get('depth'),access:f.get('access'),notes:f.get('notes'),photos:[...(o?.photos||[]),...pp],createdAt:o?.createdAt||now()};await put('spots',x);$('#modal').close();render()};$('#sdelete')?.addEventListener('click',async()=>{if(confirm('Spot wirklich löschen?')){await del('spots',o.id);$('#modal').close();render()}})"
new_spot="$('#sf').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),newWater=f.get('waterId'),referenced=o&&(d.events.some(e=>e.spotId===o.id)||d.days.some(day=>(day.spotSessions||[]).some(ss=>ss.spotId===o.id)));if(o&&referenced&&newWater!==o.waterId){alert('Dieser Spot wird bereits in Ereignissen oder Angeltagen verwendet. Das Gewässer kann deshalb nicht geändert werden.');return}let pp=await imgs(e.target.photos.files),x={...(o||{}),id:o?.id||crypto.randomUUID(),waterId:newWater,number:no,label:f.get('label'),lat:+f.get('lat')||'',lon:+f.get('lon')||'',depth:f.get('depth'),access:f.get('access'),notes:f.get('notes'),photos:[...(o?.photos||[]),...pp],createdAt:o?.createdAt||now()};await put('spots',x);$('#modal').close();render()};$('#sdelete')?.addEventListener('click',async()=>{let used=d.events.some(e=>e.spotId===o.id)||d.days.some(day=>(day.spotSessions||[]).some(ss=>ss.spotId===o.id));if(used){alert('Dieser Spot wird bereits von Ereignissen oder Angeltagen verwendet und kann deshalb nicht gelöscht werden.');return}if(confirm('Spot wirklich löschen?')){await del('spots',o.id);$('#modal').close();render()}})"
one(old_spot,new_spot,'spot guards')

start=s.index('function eventForm(type,d,o=null)')
end=s.index('\nfunction mapv(d)',start)
old=s[start:end]
new="""function eventForm(type,d,o=null){type=o?.type||type||'catch';let day=currentDay(d),wid=o?.waterId||day?.waterId||d.waters[0]?.id||'',as=activeSpotSession(day),sid=o?.spotId||as?.spotId||'',weightLb=o?.weightLb||'',eventAt=o?.at||now();show(o?`${et(type)} bearbeiten`:`Neuer Eintrag · ${et(type)}`,`<form id=\"ef\" class=\"form\"><div class=\"notice\"><b>${ei(type)} ${et(type)}</b>${o?' · Bestehende Wetterdaten bleiben erhalten.':' · Wetter wird beim Speichern automatisch aktualisiert.'}</div><button class=\"btn secondary full\" type=\"button\" id=\"eventWeather\">🌤️ Wetter jetzt aktualisieren</button><div id=\"eventWeatherPreview\">${weatherHTML(o?.weather||null)}</div>${field('at','Datum / Uhrzeit',dtLocal(eventAt),'datetime-local','required')}<div class=\"field\"><label>Gewässer</label><select name=\"waterId\" required>${d.waters.map(w=>`<option value=\"${w.id}\" ${w.id===wid?'selected':''}>${esc(w.name)}</option>`).join('')}</select></div><div class=\"field\"><label>Spot</label><select name=\"spotId\"></select></div>${['catch','bite','lost','follow'].includes(type)?selectField('species','Fischart',['Schwarzbarsch','Barsch','Zander','Hecht','Karpfen','Forelle'],o?.species||'Schwarzbarsch'):''}${['catch','lost'].includes(type)?field('length','Länge cm',o?.length||'','number','step=\"0.1\" min=\"0\"'):''}${type==='catch'?`<div class=\"field\"><label>Gewicht lbs</label><input name=\"weightLb\" type=\"number\" step=\"0.01\" min=\"0\" value=\"${esc(weightLb)}\" inputmode=\"decimal\"><small class=\"muted\" id=\"weightMetric\">${weightMetric(weightLb)?'('+weightMetric(weightLb)+')':''}</small></div>`:''}${['catch','bite','lost','follow','lureloss'].includes(type)?selectField('lure','Köder',['Chatterbait','Jig','Gummifisch','Wobbler','Spinner','Crankbait','Topwater','Texas Rig','Carolina Rig','Dropshot','Jerkbait','Sonstiger'],o?.lure||''):''}${type==='lureloss'?selectField('lossCause','Verlustursache',['Hänger','Abriss','Abriss im Drill','Sonstiger Verlust'],o?.lossCause||''):''}${type==='lureloss'?selectField('lossStructure','Struktur / Ursache',['Stein','Holz','Pflanzen','Seil / Schnur','Unbekannt'],o?.lossStructure||''):''}${area('notes','Notizen',o?.notes||'')}<div class=\"field\"><label>Fotos</label><input name=\"photos\" type=\"file\" accept=\"image/*\" multiple></div><button class=\"btn full\">Speichern</button>${o?'<button class=\"btn danger full\" type=\"button\" id=\"edelete\">Löschen</button>':''}</form>`);let snap=o?.weather||null,waterSel=$('[name=waterId]'),spotSel=$('[name=spotId]');function fillSpots(keep=''){let current=waterSel.value,opts=d.spots.filter(s=>s.waterId===current);spotSel.innerHTML=`<option value=\"\">– optional –</option>${opts.map(s=>`<option value=\"${s.id}\" ${s.id===keep?'selected':''}>${esc(spotLabel(d,s.id))}</option>`).join('')}`}fillSpots(sid);waterSel.onchange=()=>fillSpots('');let wi=$('[name=weightLb]');if(wi)wi.oninput=()=>{$('#weightMetric').textContent=weightMetric(wi.value)?`(${weightMetric(wi.value)})`:''};$('#eventWeather').onclick=async()=>{if(o){let linked=currentDay(d);if(!linked||linked.id!==o.dayId){alert('Für historische Einträge wird kein aktuelles Wetter nachgetragen. So bleiben deine alten Daten unverfälscht.');return}}try{snap=await freshWeather();$('#eventWeatherPreview').innerHTML=weatherHTML(snap)}catch{alert('Wetter gerade nicht erreichbar.')}};$('#ef').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),pp=await imgs(e.target.photos.files),wl=f.get('weightLb')||'',at=new Date(f.get('at')),waterId=f.get('waterId'),spotId=f.get('spotId');if(Number.isNaN(at.getTime())){alert('Bitte ein gültiges Datum und eine gültige Uhrzeit eingeben.');return}if(wl&&(!Number.isFinite(Number(wl))||Number(wl)<0)){alert('Bitte ein gültiges Gewicht eingeben.');return}if(type==='lureloss'&&!f.get('lossCause')){alert('Bitte eine Verlustursache auswählen.');return}if(spotId&&d.spots.find(s=>s.id===spotId)?.waterId!==waterId){alert('Der ausgewählte Spot gehört nicht zu diesem Gewässer.');return}if(!snap&&!o){try{snap=await freshWeather()}catch{}}let eventDayId=o?(o.dayId||''):(day?.id||'');let x={...(o||{}),id:o?.id||crypto.randomUUID(),type,waterId,spotId,dayId:eventDayId,species:f.get('species')||'',length:f.get('length')||'',weightLb:wl,weightKg:wl?Number(wl)*0.45359237:null,lure:f.get('lure')||'',lossCause:f.get('lossCause')||'',lossStructure:f.get('lossStructure')||'',notes:f.get('notes'),photos:[...(o?.photos||[]),...pp],weather:snap,weatherPending:!snap,at:at.toISOString()};await put('events',x);let linkedDay=eventDayId?d.days.find(dd=>dd.id===eventDayId):null;if(linkedDay&&snap&&!o){linkedDay.weatherSnapshots=[...(linkedDay.weatherSnapshots||[]),snap];await put('days',linkedDay)}$('#modal').close();render()};$('#edelete')?.addEventListener('click',async()=>{if(confirm('Eintrag wirklich löschen?')){await del('events',o.id);$('#modal').close();render()}})}"""
s=s[:start]+new+s[end:]

old_day="if(end&&end<start){alert('Das Ende kann nicht vor dem Start liegen.');return}day.waterId=f.get('waterId');day.startedAt=start.toISOString();"
new_day="if(end&&end<start){alert('Das Ende kann nicht vor dem Start liegen.');return}let newWater=f.get('waterId');if(newWater!==day.waterId&&((day.spotSessions||[]).length||d.events.some(e=>e.dayId===day.id))){alert('Dieser Angeltag enthält bereits Spot-Zeiten oder Ereignisse. Das Gewässer kann deshalb nicht geändert werden.');return}day.waterId=newWater;day.startedAt=start.toISOString();"
one(old_day,new_day,'day water guard')

one("const APP_VERSION='0.5.0-dev2';","const APP_VERSION='0.5.0-dev3';",'version')
